namespace rinkfit::gpu_rows {
namespace {
using Json=eventio::Json;using Clock=std::chrono::steady_clock;
double ms(Clock::time_point t){return std::chrono::duration<double,std::milli>(Clock::now()-t).count();}
void require(bool x,const char*reason){if(!x)throw std::runtime_error(std::string("GPU row UV: ")+reason);}
std::string topology(const EventModel&m){
 Json j{{"schema",m.schema},{"model_id",m.model_id},{"source_identity",m.source_identity},{"R0",m.R0_seed},{"n",m.n_seed},{"b",m.b_seed},{"t1",m.n_tangent1},{"t2",m.n_tangent2},{"f_ref",m.f_ref},{"Rmax",m.radius_max},{"dt",m.dt},{"first",m.first_control_time},{"nc",m.n_controls},{"cb",m.control_block_begin},{"dep",m.dependent_control},{"ref",m.reference_indices},{"refw",m.reference_weights},{"tau_bound",m.tau_bound}};
 j["blocks"]=Json::array();for(const auto&b:m.blocks)j["blocks"].push_back({{"name",b.name},{"size",b.values.size()},{"constant",b.constant},{"fixed",b.fixed_indices},{"lower",b.lower},{"upper",b.upper},{"scales",b.scales}});
 j["materials"]=Json::array();for(const auto&mat:m.materials){Json q{{"label",mat.label},{"paths",Json::array()}};for(const auto&p:mat.paths)q["paths"].push_back({{"kind",p.kind},{"geometry",p.geometry_block},{"advertisement",p.advertisement_block},{"shared_station",p.shared_station_block},{"radius",p.radius_index},{"boundary_segment",p.boundary_segment},{"physical_point",p.physical_point},{"closed",p.closed},{"id",p.id},{"variant",p.variant_id},{"provenance",p.provenance},{"points",p.points},{"a0",p.start_angle},{"a1",p.end_angle},{"h",p.fixed_height_fraction}});j["materials"].push_back(std::move(q));}return j.dump();
}
std::string packet_identity(const EventPacket&p){return Json{{"packet",p.packet_hash},{"semantic",p.semantic_hash},{"query",p.query_hash},{"source",p.source_hash},{"active_mask",p.active_mask_hash},{"exclusion",p.source_exclusion_hash},{"statistics",p.active_statistics_hash},{"component",p.source_component_recovery_hash},{"component_evidence",p.source_component_evidence_hash},{"generator",p.source_generator_recovery_hash},{"order",p.source_order_overlay_hash}}.dump();}
bool same(const EventRowLayout&a,const EventRowLayout&b){return a.block_ids==b.block_ids&&a.global_slot==b.global_slot&&a.geometry_slot==b.geometry_slot&&a.advertisement_slot==b.advertisement_slot&&a.shared_station_slot==b.shared_station_slot&&a.control_ids==b.control_ids&&a.control_slots==b.control_slots&&a.frame_time==b.frame_time&&a.material==b.material&&a.path==b.path;}
std::string digest(const std::string&s){return eventio::sha256(std::vector<std::uint8_t>(s.begin(),s.end()));}
}
struct RowUVCache::Impl {
 void*handle=nullptr;std::string topo,packet;std::vector<int>offsets,dims;std::vector<std::uint32_t>branch,material,variant;std::vector<std::uint8_t>kind,active,cpu_only;std::vector<std::int64_t>pts;std::vector<std::uint64_t>source;
 std::vector<EventRowLayout>layouts;std::vector<std::size_t>starts;std::vector<UVPartial>partials;std::vector<UVRow>rows;std::vector<Vec2<double>>primal;std::vector<double>values;std::vector<std::vector<double>>block_values;Json report;bool ready=false;
 ~Impl(){rf_uv_destroy(handle);}
};
RowUVCache::RowUVCache(const EventModel&m,const EventPacket&p,const std::vector<std::uint32_t>&branch):impl_(new Impl){
 const auto start=Clock::now();auto&x=*impl_;const auto n=p.rows.size();require(n>0&&n<=std::size_t(std::numeric_limits<int>::max()),"row count outside ABI");require(branch.size()==n,"branch must cover every raw source row");require(p.statistics_complete,"complete original W statistics required");require(!p.semantic_hash.empty()&&!p.query_hash.empty(),"loaded semantic and exact query identities required");
 x.topo=topology(m);x.packet=packet_identity(p);x.branch=branch;x.kind=p.kind;x.active=p.active_mask;x.cpu_only.assign(n,0);x.pts=p.pts;x.source=p.rows;x.material.resize(n);x.variant.resize(n);x.layouts.resize(n);x.starts.resize(n+1);x.rows.resize(n);x.primal.resize(n);x.values.reserve(8192);x.block_values.resize(m.blocks.size());
 GPUMeta meta{};std::copy(m.R0_seed.begin(),m.R0_seed.end(),meta.R0);for(int j=0;j<3;j++){meta.n[j]=m.n_seed[j];meta.b[j]=m.b_seed[j];meta.t1[j]=m.n_tangent1[j];meta.t2[j]=m.n_tangent2[j];}meta.fref=m.f_ref;meta.Rmax=m.radius_max;meta.dt=m.dt;meta.first=m.first_control_time;meta.nc=m.n_controls;meta.cb=m.control_block_begin;meta.dep=m.dependent_control;for(int j=0;j<4;j++){meta.ref[j]=m.reference_indices[j];meta.refw[j]=m.reference_weights[j];}
 for(const auto&b:m.blocks){require(!b.values.empty(),"empty physical block unsupported");x.offsets.push_back(int(x.values.size()));x.dims.push_back(int(b.values.size()));x.values.insert(x.values.end(),b.values.begin(),b.values.end());}
 std::vector<GPUPath>paths;std::vector<double>points;std::vector<std::vector<int>>pathmap;
 for(const auto&mat:m.materials){std::vector<int>map;for(const auto&p:mat.paths){require(p.kind>=0&&p.kind<=3,"unknown material kind unsupported");if(p.kind==0||p.kind==1)require(p.geometry_block>=0&&std::size_t(p.geometry_block)<m.blocks.size(),"ice geometry block missing");if(p.kind==0)require(x.dims[p.geometry_block]>=4,"segment geometry shape unsupported");if(p.kind==1)require(p.radius_index>=0&&p.radius_index<x.dims[p.geometry_block]&&x.dims[p.geometry_block]>=2,"circle geometry shape unsupported");if(p.kind==2){require(p.advertisement_block>=0&&std::size_t(p.advertisement_block)<m.blocks.size()&&x.dims[p.advertisement_block]==4,"board advertisement shape unsupported");require(!p.points.empty(),"empty board path unsupported");if(p.geometry_block>=0)require(std::size_t(p.geometry_block)<m.blocks.size()&&x.dims[p.geometry_block]==6,"board affine shape unsupported");}if(p.kind==3)require(p.boundary_segment>=-1&&p.boundary_segment<8,"boundary segment unsupported");
 map.push_back(int(paths.size()));GPUPath q{};q.kind=p.kind;q.geom=p.geometry_block;q.ad=p.advertisement_block;q.ri=p.radius_index;q.bs=p.boundary_segment;q.a0=p.start_angle;q.a1=p.end_angle;q.h=p.fixed_height_fraction;q.begin=int(points.size()/2);q.count=int(p.points.size());for(auto uv:p.points){points.push_back(uv[0]);points.push_back(uv[1]);}paths.push_back(q);}pathmap.push_back(map);}
 std::vector<int>bids,ci,cs;std::vector<UVLayout>layouts(n);std::vector<UVJob>jobs;std::size_t maxcols=0,maxblocks=0;
 for(std::size_t i=0;i<n;i++){
 x.starts[i]=jobs.size();x.material[i]=p.model_material(i);require(x.material[i]<m.materials.size(),"material mapping out of range");require(branch[i]<m.materials[x.material[i]].paths.size(),"finite path branch out of range");const auto&path=m.materials[x.material[i]].paths[branch[i]];require(path.variant_id==p.model_variant_id(i),"finite semantic variant changed");x.variant[i]=p.resolved_variant.empty()?p.variant[i]:p.resolved_variant[i];
 const double t=(p.pts[i]-256256)/12800.;x.rows[i].t=t;if(!p.is_active(i))continue;
 auto l=m.layout(x.material[i],branch[i],t);x.layouts[i]=l;if(path.shared_station_block>=0){x.cpu_only[i]=1;continue;}require(l.block_ids.size()+4<=32,"local block storage unsupported; CPU fallback required");require(l.global_slot>=0&&std::size_t(l.global_slot)<l.block_ids.size()&&x.dims[l.block_ids[l.global_slot]]==32,"global block ABI unsupported");require(l.control_ids.size()==l.control_slots.size(),"control slot identity mismatch");int nc=4;for(int b:l.block_ids){require(b>=0&&std::size_t(b)<x.dims.size(),"dependency block outside model");nc+=x.dims[b];}require(nc<=160,"local column storage unsupported; CPU fallback required");for(std::size_t k=0;k<l.control_slots.size();k++)require(l.control_slots[k]>=0&&std::size_t(l.control_slots[k])<l.block_ids.size()&&x.dims[l.block_ids[l.control_slots[k]]]==3,"control dependency ABI unsupported");
 layouts[i]={l.global_slot,l.geometry_slot,l.advertisement_slot,pathmap[x.material[i]][branch[i]],int(bids.size()),int(l.block_ids.size()),int(ci.size()),int(l.control_ids.size())};bids.insert(bids.end(),l.block_ids.begin(),l.block_ids.end());ci.insert(ci.end(),l.control_ids.begin(),l.control_ids.end());cs.insert(cs.end(),l.control_slots.begin(),l.control_slots.end());for(int c=0;c<nc;c++)jobs.push_back({int(i),c});maxcols=std::max(maxcols,std::size_t(nc));maxblocks=std::max(maxblocks,l.block_ids.size()+4);
 }x.starts[n]=jobs.size();require(jobs.size()<std::size_t(std::numeric_limits<int>::max()),"job count outside ABI");x.partials.resize(jobs.size());UVTiming timing{};char error[1024]{};
 int rc=rf_uv_create(&meta,x.offsets.data(),x.dims.data(),int(x.dims.size()),int(x.values.size()),paths.data(),int(paths.size()),points.data(),int(points.size()),bids.data(),int(bids.size()),ci.data(),cs.data(),int(ci.size()),layouts.data(),int(n),jobs.data(),int(jobs.size()),&x.handle,&timing,error,sizeof(error));if(rc)throw std::runtime_error(error);
 x.report={{"schema","rinkfit.persistent_CUDA_raw_UV_partial_cache.v1"},{"raw_rows",n},{"active_rows",p.active_rows.size()},{"CPU_shared_station_rows",std::count(x.cpu_only.begin(),x.cpu_only.end(),std::uint8_t(1))},{"excluded_rows",p.excluded_rows},{"model_paths",paths.size()},{"local_columns_including_4aux",jobs.size()},{"max_local_columns",maxcols},{"max_local_blocks_including_4aux",maxblocks},{"topology_sha256",digest(x.topo)},{"packet_identity",Json::parse(x.packet)},{"cuda_setup_ms",timing.setup_ms},{"host_and_cuda_setup_ms",ms(start)},{"raw_UV_only",true},{"CPU_authoritative_primal",true},{"CPU_primal_is_zero_seed_Ceres_Jet1_same_scalar_path_as_AD64",true},{"all_values_uploaded_every_evaluate",true},{"unsupported_or_invalid_rejected",true},{"no_Solve",true},{"alpha_budget_UV_zeros_are_exact_Jet_results",true}};
}
RowUVCache::~RowUVCache()=default;
void RowUVCache::evaluate(const EventModel&m,const EventPacket&p,const std::vector<std::uint32_t>&branch,const std::vector<double>&S,const std::vector<double>&V,const std::vector<double>&alpha,double b,const std::string&state_identity){
 auto&x=*impl_;x.ready=false;const auto start=Clock::now();const auto n=x.rows.size();require(S.size()==n&&V.size()==n&&alpha.size()==n,"four auxiliary row state coverage mismatch");require(!state_identity.empty(),"explicit current state identity required");require(topology(m)==x.topo,"model/layout/gauge topology changed; rebuild cache");require(packet_identity(p)==x.packet&&branch==x.branch&&p.rows==x.source&&p.pts==x.pts&&p.kind==x.kind&&p.active_mask==x.active,"packet/semantic/branch/active identity changed; rebuild cache");
 x.values.clear();for(std::size_t j=0;j<m.blocks.size();j++){x.block_values[j]=m.blocks[j].values;for(double z:m.blocks[j].values){require(std::isfinite(z),"nonfinite physical theta");x.values.push_back(z);}}
 require(std::isfinite(b),"nonfinite budget primal");double primal_ms=0;const auto primstart=Clock::now();
 for(std::size_t i=0;i<n;i++){require(p.model_material(i)==x.material[i]&&(p.resolved_variant.empty()?p.variant[i]:p.resolved_variant[i])==x.variant[i],"resolved row correspondence changed; rebuild cache");x.rows[i].s=S[i];x.rows[i].v=V[i];x.rows[i].alpha=alpha[i];x.rows[i].budget=b;if(!x.active[i])continue;require(std::isfinite(S[i])&&S[i]>=0&&S[i]<=1&&std::isfinite(V[i])&&std::isfinite(alpha[i]),"nonfinite/outside finite auxiliary primal; CPU fallback required");// Ceres Jet division evaluates its scalar via reciprocal multiplication.
 // A plain double replay can differ by ulps and is not the AD primal.
 // The zero-seeded Jet1 replay preserves the exact CPU AD scalar path.
 using J=ceres::Jet<double,1>;std::vector<J>storage;storage.reserve(160);std::vector<const J*>pars;pars.reserve(32);for(int id:x.layouts[i].block_ids){pars.push_back(storage.data()+storage.size());for(double value:m.blocks[id].values)storage.emplace_back(value);}const auto pred=m.predict_for_al(x.layouts[i],J(S[i]),J(V[i]),pars.data());require(pred.arithmetic_valid,"CPU authoritative projection invalid; CPU fallback required");x.primal[i]={pred.uv[0].a,pred.uv[1].a};
 }primal_ms=ms(primstart);UVTiming timing{};char error[1024]{};int rc=rf_uv_evaluate(x.handle,x.values.data(),int(x.values.size()),x.rows.data(),int(n),x.partials.data(),int(x.partials.size()),&timing,error,sizeof(error));if(rc)throw std::runtime_error(error);
 for(const auto&z:x.partials)require(z.arithmetic&&std::isfinite(z.u)&&std::isfinite(z.v),"GPU arithmetic invalid; discard complete cache and use CPU");
 std::vector<std::uint8_t>statebytes;auto append=[&](const void*p,std::size_t count){const auto*q=static_cast<const std::uint8_t*>(p);statebytes.insert(statebytes.end(),q,q+count);};append(x.values.data(),x.values.size()*sizeof(double));for(const auto*vec:{&S,&V,&alpha})append(vec->data(),vec->size()*sizeof(double));append(&b,sizeof(b));
 x.report["evaluation"]={{"state_identity",state_identity},{"uploaded_theta_and_4aux_sha256",eventio::sha256(statebytes)},{"CPU_authoritative_primal_ms",primal_ms},{"GPU_H2D_ms",timing.h2d_ms},{"GPU_kernel_ms",timing.kernel_ms},{"GPU_D2H_ms",timing.d2h_ms},{"GPU_upload_compute_download_ms",timing.total_ms},{"host_state_check_primal_transfer_compute_ms",ms(start)},{"GPU_batches",timing.batches}};x.ready=true;
}
Projection RowUVCache::projection(const EventModel&m,std::size_t i,const EventRowLayout&l,double s,double v)const{
 const auto&x=*impl_;require(x.ready,"evaluate current theta before requesting partials");require(i<x.rows.size()&&x.active[i],"excluded/missing raw row has no cache entry");require(!x.cpu_only[i],"shared station row requires original CPU projection_ad");require(s==x.rows[i].s&&v==x.rows[i].v&&same(l,x.layouts[i]),"row primal/layout changed; evaluate new state or CPU boundary fallback");
 Projection out;out.ids=l.block_ids;out.uv=x.primal[i];out.nuisance={s,v};std::size_t col=0;
 for(int id:l.block_ids){require(m.blocks.at(id).values==x.block_values.at(id),"physical theta changed since evaluate; stale cache refused");const auto size=x.dims[id];out.jac.emplace_back(2*size);auto&j=out.jac.back();for(int c=0;c<size;c++,col++){const auto&d=x.partials[x.starts[i]+col];j[c]=d.u;j[size+c]=d.v;}}
 const auto&ds=x.partials[x.starts[i]+col];const auto&dv=x.partials[x.starts[i]+col+1];out.jac.push_back({ds.u,dv.u,ds.v,dv.v});return out;
}
bool RowUVCache::cpu_fallback(std::size_t row)const{const auto&x=*impl_;require(row<x.rows.size(),"raw row out of range");return x.cpu_only[row]!=0;}
const UVPartial&RowUVCache::partial(std::size_t row,std::size_t col)const{const auto&x=*impl_;require(x.ready,"no evaluated state");require(row<x.rows.size()&&col<x.starts[row+1]-x.starts[row],"local column out of range");return x.partials[x.starts[row]+col];}
std::size_t RowUVCache::local_columns(std::size_t row)const{const auto&x=*impl_;require(row<x.rows.size(),"raw row out of range");return x.starts[row+1]-x.starts[row];}
std::size_t RowUVCache::total_columns()const{return impl_->partials.size();}
const eventio::Json&RowUVCache::report()const{return impl_->report;}
} // namespace rinkfit::gpu_rows
